function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Logger' || args[0].length !== 0) return 'Start with Logger and no arguments.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to shouldPrintMessage.';
  let last = 0;
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'shouldPrintMessage') return 'Only shouldPrintMessage can follow the constructor.';
    const [timestamp, message] = args[i];
    if (!Number.isInteger(timestamp) || timestamp < 0 || timestamp > 1000000000) return 'timestamp is an integer from 0 to 10^9.';
    if (timestamp < last) return 'Timestamps must never decrease.';
    if (typeof message !== 'string' || message.length < 1 || message.length > 30) return 'message has 1 to 30 characters.';
    last = timestamp;
  }
  return null;
}

