class Logger {
  constructor() {
    this.nextAllowed = new Map();
  }

  shouldPrintMessage(timestamp, message) {
    const allowedAt = this.nextAllowed.get(message);
    if (allowedAt !== undefined && timestamp < allowedAt) {
      return false;
    }
    this.nextAllowed.set(message, timestamp + 10);
    return true;
  }
}

