class Logger {
  constructor() {
    this.printed = [];
  }
  shouldPrintMessage(timestamp, message) {
    for (const [time, text] of this.printed) {
      if (text === message && timestamp - time < 10) return false;
    }
    this.printed.push([timestamp, message]);
    return true;
  }
}

