function generate(rand, size) {
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (length) => Array.from({ length }, () => letters[Math.floor(rand() * 26)]).join('');
  const poolSize = large ? 30 : 1 + Math.floor(rand() * 3);
  const pool = Array.from({ length: poolSize }, () => word(1 + Math.floor(rand() * (large || rand() < 0.2 ? 30 : 3))));
  const calls = large ? 499 : 1 + Math.floor(rand() * 12);
  const maxStep = large ? 4 : [0, 3, 6, 12][Math.floor(rand() * 4)];
  let timestamp = large || rand() < 0.15 ? 1000000000 - calls * maxStep : Math.floor(rand() * 5);
  const operations = ['Logger'];
  const args = [[]];
  for (let i = 0; i < calls; i++) {
    timestamp += rand() < 0.3 ? 0 : Math.floor(rand() * (maxStep + 1));
    operations.push('shouldPrintMessage');
    args.push([timestamp, pool[Math.floor(rand() * pool.length)]]);
  }
  return [operations, args];
}
